INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21F2QYO', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What value of $x$ satisfies the equation $4x - 11 = 37$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'Adding 11 to both sides gives $4x = 48$. Dividing both sides by 4 gives $x = 12$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21FIVPD', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'Which of the following gives all solutions to the equation $\\frac{x^2 - 9}{x - 3} = 5$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 2$ only"},{"key":"B","text":"$x = 2$ and $x = 3$"},{"key":"C","text":"$x = 3$ only"},{"key":"D","text":"$x = -2$ only"}]$lyceon_json$::jsonb, 'A', NULL, E'For $x \\neq 3$, factor the numerator: $\\frac{(x - 3)(x + 3)}{x - 3} = x + 3$. Setting $x + 3 = 5$ gives $x = 2$. Note that $x = 3$ must be excluded because it makes the original denominator zero. The distractor $x = 2$ and $x = 3$ includes the excluded value without checking the domain restriction. The distractor $x = 3$ only confuses the excluded value with the solution. The distractor $x = -2$ results from a sign error when solving $x + 3 = 5$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21J9GIF', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'If $-4x + 9 \\geq 2x - 21$, what is the greatest integer value of $x$ that satisfies this inequality?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Starting with $-4x + 9 \\geq 2x - 21$, subtract $2x$ from both sides to get $-6x + 9 \\geq -21$. Then subtract $9$ from both sides: $-6x \\geq -30$. Dividing both sides by $-6$ and flipping the inequality sign gives $x \\leq 5$. The greatest integer satisfying $x \\leq 5$ is $5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM224P62W', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A printer produces $37$ pages every $2$ minutes. At this constant rate, how many minutes will it take to print $629$ pages?', NULL, $lyceon_json$[{"key":"A","text":"$17$"},{"key":"B","text":"$34$"},{"key":"C","text":"$37$"},{"key":"D","text":"$1{,}258$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{37 \\text{ pages}}{2 \\text{ minutes}}$. To find the time for $629$ pages, divide: $629 \\div 37 = 17$ groups of $37$ pages. Each group takes $2$ minutes, so the total time is $17 \\times 2 = 34$ minutes. The answer $17$ results from finding the number of groups but not multiplying by $2$ minutes per group. The answer $37$ confuses the rate with the time. The answer $1{,}258$ comes from incorrectly multiplying $629 \\times 2$ instead of dividing first.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22A1HCF', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{10x^4 - 15x^3 + 20x^2}{5x^2}$ for $x \\neq 0$?', NULL, $lyceon_json$[{"key":"A","text":"$2x^2 - 3x + 4$"},{"key":"B","text":"$2x^4 - 3x^3 + 4x^2$"},{"key":"C","text":"$2x^2 - 3x + 20$"},{"key":"D","text":"$2x^2 + 3x + 4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Divide each term by $5x^2$: $\\frac{10x^4}{5x^2} = 2x^2$, $\\frac{-15x^3}{5x^2} = -3x$, and $\\frac{20x^2}{5x^2} = 4$. The result is $2x^2 - 3x + 4$. The distractor $2x^4 - 3x^3 + 4x^2$ divides only the coefficients by 5 without reducing the exponents of $x$. The distractor $2x^2 - 3x + 20$ fails to divide the last term''s coefficient by 5. The distractor $2x^2 + 3x + 4$ drops the negative sign on the middle term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22AY2KH', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'If $(3x + 4)(2x - 5) = 6x^2 + bx - 20$ for all values of $x$, what is the value of $b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-7', ARRAY['-7'], E'Expand the left side using FOIL: $(3x)(2x) = 6x^2$, $(3x)(-5) = -15x$, $(4)(2x) = 8x$, and $(4)(-5) = -20$. Combining: $6x^2 + (-15x + 8x) - 20 = 6x^2 - 7x - 20$. Matching coefficients with $6x^2 + bx - 20$ gives $b = -7$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22FU2YO', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the value of $x$ in the equation $\\frac{3x + 7}{5} - \\frac{x - 3}{2} = 4$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$11$"},{"key":"C","text":"$29$"},{"key":"D","text":"$-11$"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiplying every term by the least common denominator 10 gives $2(3x + 7) - 5(x - 3) = 40$. Distributing yields $6x + 14 - 5x + 15 = 40$, which simplifies to $x + 29 = 40$, so $x = 11$. The value $29$ comes from stopping at the intermediate step $x + 29 = 40$ and taking the constant instead of isolating $x$. The value $-11$ results from a sign error in the final step. The value $3$ arises from a distribution error when expanding $-5(x - 3)$ as $-5x - 15$ instead of $-5x + 15$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22J9S6T', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $4(3x - 8) - 2(5x + 3)$?', NULL, $lyceon_json$[{"key":"A","text":"$2x - 26$"},{"key":"B","text":"$22x - 38$"},{"key":"C","text":"$2x - 38$"},{"key":"D","text":"$2x + 26$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distribute each coefficient: $4(3x - 8) = 12x - 32$ and $-2(5x + 3) = -10x - 6$. Combining gives $(12x - 10x) + (-32 - 6) = 2x - 38$. The distractor $2x - 26$ results from computing $-32 + 6$ instead of $-32 - 6$, failing to distribute the negative sign to the second term. The distractor $22x - 38$ adds $12x + 10x$ instead of subtracting. The distractor $2x + 26$ reverses the sign of the entire constant.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM231X2O2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles of a triangle measure $47^\\circ$ and $58^\\circ$. What is the measure, in degrees, of the third angle?', NULL, $lyceon_json$[{"key":"A","text":"$65$"},{"key":"B","text":"$75$"},{"key":"C","text":"$85$"},{"key":"D","text":"$105$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of any triangle is $180^\\circ$. Subtracting the two known angles gives $180 - 47 - 58 = 75^\\circ$. The value $65$ results from a subtraction error. The value $85$ also results from a subtraction error. The value $105$ comes from adding $47 + 58$ instead of subtracting from $180$, confusing the angle sum property.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23ADVKN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers wanted to determine whether a new teaching method improves test scores compared to the traditional method. They randomly assigned $120$ students to two groups: one group used the new method, and the other used the traditional method. At the end of the semester, the group using the new method had significantly higher average test scores. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new teaching method caused the improvement in test scores."},{"key":"B","text":"Students who prefer the new method tend to score higher on tests."},{"key":"C","text":"The new method is associated with higher test scores, but a causal relationship cannot be established."},{"key":"D","text":"The results prove that all students nationwide would benefit from the new teaching method."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the researchers randomly assigned students to the two groups, this is a randomized controlled experiment. Random assignment controls for confounding variables, which allows a causal conclusion: the new teaching method caused the higher test scores. The claim about student preference introduces information not present in the study design. The claim that causation cannot be established would apply to an observational study, not a randomized experiment with random assignment. The claim that results apply to all students nationwide overgeneralizes beyond the study''s sample; the causal conclusion applies to the studied population, not necessarily to all students everywhere.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23CRWWE', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The expression $\\frac{8x^3 - 27}{2x - 3}$ can be written as $ax^2 + bx + c$ for $x \\neq \\frac{3}{2}$, where $a$, $b$, and $c$ are constants. What is the value of $a + b + c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19', ARRAY['19'], E'Recognize $8x^3 - 27 = (2x)^3 - 3^3$ as a difference of cubes. Apply the factoring identity $p^3 - q^3 = (p - q)(p^2 + pq + q^2)$ with $p = 2x$ and $q = 3$: $8x^3 - 27 = (2x - 3)(4x^2 + 6x + 9)$. Dividing by $(2x - 3)$ gives $4x^2 + 6x + 9$. Therefore $a = 4$, $b = 6$, and $c = 9$, so $a + b + c = 4 + 6 + 9 = 19$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM267EXSL', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A delivery service charges a flat fee of $\\$11$ plus $\\$3$ per package. A customer has a budget of no more than $\\$53$. What is the maximum number of packages the customer can send?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$14$"},{"key":"C","text":"$15$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $p$ be the number of packages. The inequality is $11 + 3p \\leq 53$, which gives $3p \\leq 42$, so $p \\leq 14$. The maximum is $14$ packages. Choosing $13$ results from a rounding or subtraction error. Choosing $15$ comes from solving $3p \\leq 42$ but then rounding up instead of recognizing the answer is exactly $14$, or from an error in subtracting the flat fee. Choosing $21$ results from ignoring the flat fee entirely and computing $53 \\div 3 \\approx 17.67$, then further miscalculating, or dividing $63$ by $3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26R4U9G', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $DEF$, the measures of the angles are $(2x + 11)^\\circ$, $(3x - 7)^\\circ$, and $(x + 26)^\\circ$. What is the measure, in degrees, of the largest angle?', NULL, $lyceon_json$[{"key":"A","text":"$25$"},{"key":"B","text":"$51$"},{"key":"C","text":"$61$"},{"key":"D","text":"$68$"}]$lyceon_json$::jsonb, 'D', NULL, E'The sum of the angles of a triangle is $180^\\circ$: $(2x + 11) + (3x - 7) + (x + 26) = 180$, which simplifies to $6x + 30 = 180$, so $x = 25$. The three angles are $2(25) + 11 = 61^\\circ$, $3(25) - 7 = 68^\\circ$, and $25 + 26 = 51^\\circ$. The largest angle is $68^\\circ$. The value $25$ is just the value of $x$, not an angle measure. The values $51$ and $61$ are the other two angles, not the largest.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26UP66P', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The quadratic function $q(x) = 2x^2 - 28x + 89$ can be written in the form $q(x) = 2(x - h)^2 + k$. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-9', ARRAY['-9'], E'To rewrite $q(x) = 2x^2 - 28x + 89$ in vertex form, factor out the leading coefficient from the first two terms: $q(x) = 2(x^2 - 14x) + 89$. Complete the square inside the parentheses: half of $-14$ is $-7$, and $(-7)^2 = 49$. So $q(x) = 2(x^2 - 14x + 49 - 49) + 89 = 2(x - 7)^2 - 98 + 89 = 2(x - 7)^2 - 9$. Therefore $k = -9$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26WEOMW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'What is the $y$-intercept of the function $g(x) = 2x^3 - 5x^2 + 13x - 19$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 13)$"},{"key":"B","text":"$(0, -5)$"},{"key":"C","text":"$(0, -19)$"},{"key":"D","text":"$(0, 2)$"}]$lyceon_json$::jsonb, 'C', NULL, E'The $y$-intercept of a function is found by evaluating $g(0)$. Substituting $x = 0$ gives $g(0) = 0 - 0 + 0 - 19 = -19$, so the $y$-intercept is $(0, -19)$. The point $(0, 13)$ incorrectly selects the coefficient of $x$. The point $(0, -5)$ incorrectly selects the coefficient of $x^2$. The point $(0, 2)$ incorrectly selects the leading coefficient.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26ZH7V4', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $6x - 9y = c$ and $-2x + 3y = 7$ has infinitely many solutions. What is the value of $c$?', NULL, $lyceon_json$[{"key":"A","text":"$-21$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$7$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'A', NULL, E'For the system to have infinitely many solutions, the two equations must be equivalent. Multiplying the second equation $-2x + 3y = 7$ by $-3$ gives $6x - 9y = -21$. For this to be the same as the first equation, $c = -21$. The value $-7$ comes from not multiplying the right-hand side by $-3$, or only dividing the first equation''s coefficients by $3$ without adjusting the sign. The value $7$ results from ignoring the negative sign when multiplying by $-3$. The value $21$ comes from multiplying by $3$ instead of $-3$, losing the sign.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27HFUN4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = -2x^3 + 5x$. As $x$ increases without bound, which of the following best describes the end behavior of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$f(x)$ increases without bound"},{"key":"B","text":"$f(x)$ decreases without bound"},{"key":"C","text":"$f(x)$ approaches $0$"},{"key":"D","text":"$f(x)$ approaches $5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The end behavior of a polynomial is determined by its leading term. The leading term of $f(x) = -2x^3 + 5x$ is $-2x^3$. Because the leading coefficient is negative and the degree is odd, as $x$ increases without bound, $f(x)$ decreases without bound. The claim that $f(x)$ increases without bound ignores the negative leading coefficient. The claim that $f(x)$ approaches $0$ confuses polynomial end behavior with that of a rational function. The claim that $f(x)$ approaches $5$ incorrectly treats the linear coefficient as a horizontal asymptote.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27MDGIJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $y = x + 5$ and $y = x^2 + 2x - 1$, what is the value of $y$ at the solution where $x > 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Set the expressions equal: $x + 5 = x^2 + 2x - 1$. Rearrange: $0 = x^2 + x - 6$. Factor: $(x + 3)(x - 2) = 0$, so $x = -3$ or $x = 2$. The positive solution is $x = 2$. Substituting into $y = x + 5$ gives $y = 2 + 5 = 7$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29LW72T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A dataset contains the values: $8, 12, 15, 15, 19, 22, 29$. If the value $29$ is removed from the dataset, which of the following correctly describes the change in the mean and the median?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases, and the median stays the same."},{"key":"B","text":"The mean decreases, and the median decreases."},{"key":"C","text":"The mean stays the same, and the median decreases."},{"key":"D","text":"The mean increases, and the median stays the same."}]$lyceon_json$::jsonb, 'A', NULL, E'The original dataset has $7$ values with a sum of $120$, so the mean is $\\frac{120}{7} \\approx 17.1$, and the median (the 4th value) is $15$. After removing $29$, the $6$ remaining values sum to $91$, giving a mean of $\\frac{91}{6} \\approx 15.2$, while the median becomes $\\frac{15 + 15}{2} = 15$. The mean decreases because the removed value was above the original mean, and the median remains $15$. The claim that the median also decreases is incorrect because both middle values in the reduced set are $15$. The claim that the mean increases contradicts the removal of a value greater than the mean.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29UFJWL', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{3}{x - 5} + \\frac{2}{x + 1}$ for $x \\neq 5$ and $x \\neq -1$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5x + 13}{x^2 - 4x - 5}$"},{"key":"B","text":"$\\frac{5}{x^2 - 4x - 5}$"},{"key":"C","text":"$\\frac{5x - 7}{x^2 - 4x - 5}$"},{"key":"D","text":"$\\frac{5x - 7}{x^2 + 4x - 5}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Find a common denominator $(x - 5)(x + 1) = x^2 - 4x - 5$. The numerator becomes $3(x + 1) + 2(x - 5) = 3x + 3 + 2x - 10 = 5x - 7$. The combined expression is $\\frac{5x - 7}{x^2 - 4x - 5}$. The distractor $\\frac{5x + 13}{x^2 - 4x - 5}$ computes $3(x + 1) + 2(x + 5) = 5x + 13$, mishandling the sign in the second numerator. The distractor $\\frac{5}{x^2 - 4x - 5}$ simply adds the numerators $3 + 2 = 5$ without cross-multiplying. The distractor $\\frac{5x - 7}{x^2 + 4x - 5}$ has the correct numerator but incorrectly expands the denominator, getting the sign of the middle term wrong.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AM9N9E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collected data on the number of hours spent training and the distance, in kilometers, completed in a cycling trial. The line of best fit for the data is $y = 4.7x + 51.3$, where $x$ is the number of hours of training per week and $y$ is the predicted distance in kilometers. What is the best interpretation of the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of weekly training, the predicted distance increases by $51.3$ kilometers."},{"key":"B","text":"A cyclist who trains $0$ hours per week is predicted to complete $4.7$ kilometers."},{"key":"C","text":"For each additional hour of weekly training, the predicted distance increases by $4.7$ kilometers."},{"key":"D","text":"For each additional kilometer completed, the predicted weekly training increases by $4.7$ hours."}]$lyceon_json$::jsonb, 'C', NULL, E'In the equation $y = 4.7x + 51.3$, the slope is $4.7$. The slope represents the predicted change in the dependent variable ($y$, distance in kilometers) for each one-unit increase in the independent variable ($x$, hours of training per week). Therefore, each additional hour of weekly training is associated with a predicted increase of $4.7$ kilometers. The interpretation that the distance increases by $51.3$ kilometers confuses the slope with the $y$-intercept. The interpretation that a cyclist training $0$ hours completes $4.7$ kilometers confuses the slope with the $y$-intercept and assigns them to the wrong values. The interpretation that reverses the variables misidentifies which quantity is predicted from which.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B6AV98', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $g$ is defined by $g(x) = a(x + 4)^2 - 17$, where $a$ is a constant. If $g(1) = 58$, what is the value of $g(-2)$?', NULL, $lyceon_json$[{"key":"A","text":"$-17$"},{"key":"B","text":"$43$"},{"key":"C","text":"$-11$"},{"key":"D","text":"$-5$"}]$lyceon_json$::jsonb, 'D', NULL, E'First, find $a$ using $g(1) = 58$: substituting gives $a(1 + 4)^2 - 17 = 58$, so $25a = 75$, and $a = 3$. Then $g(x) = 3(x + 4)^2 - 17$. Evaluating $g(-2) = 3(-2 + 4)^2 - 17 = 3(4) - 17 = 12 - 17 = -5$. The value $-17$ results from stopping after finding $a$ and reporting only the constant term. The value $43$ comes from a sign error such as computing $12 + 17$ instead of $12 - 17$. The value $-11$ arises from an arithmetic slip like computing $3(2)^2 = 6$ instead of $12$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BC1AH2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $RST$, the measure of angle $R$ is $43^\\circ$ and the measure of angle $S$ is $67^\\circ$. Point $U$ lies on side $RS$ such that $TU$ bisects angle $T$. What is the measure, in degrees, of angle $TUS$?', NULL, $lyceon_json$[{"key":"A","text":"$35$"},{"key":"B","text":"$70$"},{"key":"C","text":"$78$"},{"key":"D","text":"$110$"}]$lyceon_json$::jsonb, 'C', NULL, E'First, find angle $T$: since the angles of triangle $RST$ sum to $180^\\circ$, angle $T = 180 - 43 - 67 = 70^\\circ$. Because $TU$ bisects angle $T$, the angle $STU = \\frac{70}{2} = 35^\\circ$. In triangle $STU$, the angle sum gives $\\angle TUS = 180 - 67 - 35 = 78^\\circ$. The value $35$ is just the bisected half of angle $T$, not the requested angle. The value $70$ is the full angle $T$ before bisection, obtained by stopping too early. The value $110$ results from incorrectly adding angles $R$ and $S$ as though the exterior angle theorem applies directly at $U$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BNBXK3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A tablet originally priced at $\\$130$ is on sale for $\\$104$. What is the percent discount?', NULL, $lyceon_json$[{"key":"A","text":"$25\\%$"},{"key":"B","text":"$20\\%$"},{"key":"C","text":"$26\\%$"},{"key":"D","text":"$16\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount amount is $\\$130 - \\$104 = \\$26$. The percent discount is $\\frac{26}{130} \\times 100 = 20\\%$. The answer $25\\%$ results from dividing the discount by the sale price ($\\frac{26}{104}$) instead of the original price. The answer $26\\%$ mistakes the dollar discount for the percent discount. The answer $16\\%$ comes from an arithmetic error in the division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CD09C6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $ABC$ with the right angle at $C$, $\\tan(A) = \\frac{3}{4}$. If the hypotenuse $AB$ has length $35$, what is the length of side $BC$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'Since $\\tan(A) = \\frac{BC}{AC} = \\frac{3}{4}$, let $BC = 3k$ and $AC = 4k$ for some positive value $k$. By the Pythagorean theorem, $(3k)^2 + (4k)^2 = 35^2$, which gives $9k^2 + 16k^2 = 1225$, so $25k^2 = 1225$ and $k^2 = 49$, meaning $k = 7$. Therefore $BC = 3(7) = 21$. A common error is computing $AC = 4(7) = 28$ instead, which gives the other leg rather than the one requested.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DH7ZML', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A cone has a radius of $3$ and a height of $12$. What is the volume of the cone?', NULL, $lyceon_json$[{"key":"A","text":"$12\\pi$"},{"key":"B","text":"$36\\pi$"},{"key":"C","text":"$54\\pi$"},{"key":"D","text":"$108\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(3)^2(12) = \\frac{1}{3}\\pi(9)(12) = \\frac{108\\pi}{3} = 36\\pi$. The value $12\\pi$ results from computing $\\frac{1}{3}\\pi r h = \\frac{1}{3}\\pi(3)(12)$ instead of $\\frac{1}{3}\\pi r^2 h$, forgetting to square the radius. The value $54\\pi$ comes from using $\\frac{1}{2}$ instead of $\\frac{1}{3}$ as the fraction in the volume formula. The value $108\\pi$ results from computing $\\pi r^2 h = \\pi(9)(12)$ without the $\\frac{1}{3}$ factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DN2STK', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $5(3x - 4) - 7 = 11x + 13$?', NULL, $lyceon_json$[{"key":"A","text":"$-10$"},{"key":"B","text":"$5$"},{"key":"C","text":"$10$"},{"key":"D","text":"$40$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distributing gives $15x - 20 - 7 = 11x + 13$, which simplifies to $15x - 27 = 11x + 13$. Subtracting $11x$ from both sides and adding 27 gives $4x = 40$, so $x = 10$. The value $-10$ comes from a sign error when combining like terms. The value $40$ results from not dividing by 4 in the final step. The value $5$ results from an arithmetic miscalculation during distribution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E4KNDY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the equation $3x^2 - 7x + 5 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"Zero"},{"key":"B","text":"Exactly one"},{"key":"C","text":"Exactly two"},{"key":"D","text":"Infinitely many"}]$lyceon_json$::jsonb, 'A', NULL, E'Compute the discriminant $b^2 - 4ac = (-7)^2 - 4(3)(5) = 49 - 60 = -11$. Since the discriminant is negative, the equation has zero real solutions. Choosing exactly one reflects confusion with the condition for a repeated root ($b^2 - 4ac = 0$). Choosing exactly two reflects the incorrect assumption that every quadratic has two real roots. Choosing infinitely many misunderstands the nature of polynomial equations, which have at most finitely many roots.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E8AODZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $22$. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$11\\pi$"},{"key":"B","text":"$22\\pi$"},{"key":"C","text":"$121\\pi$"},{"key":"D","text":"$484\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The radius is half the diameter: $r = \\frac{22}{2} = 11$. The area is $\\pi r^2 = \\pi(11)^2 = 121\\pi$. The value $11\\pi$ comes from computing $\\pi r$ instead of $\\pi r^2$, forgetting to square the radius. The value $22\\pi$ is the circumference $\\pi d$, not the area. The value $484\\pi$ results from using the diameter $22$ as the radius in the area formula, giving $\\pi(22)^2 = 484\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ET6MSW', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A school purchased a total of $23$ items consisting of pens and markers. Each pen costs $\\$2$ and each marker costs $\\$5$. If the total cost was $\\$82$, how many markers did the school purchase?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$11$"},{"key":"C","text":"$12$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $p$ be the number of pens and $m$ the number of markers. Then $p + m = 23$ and $2p + 5m = 82$. From the first equation, $p = 23 - m$. Substituting: $2(23 - m) + 5m = 82$, which gives $46 - 2m + 5m = 82$, so $3m = 36$ and $m = 12$. The value $11$ results from finding the number of pens instead of markers. The value $9$ comes from setting up the cost equation incorrectly, such as swapping the prices. The value $14$ results from an arithmetic error in the substitution step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FBWHYK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions of the equation $x^2 + 3x - 28 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 4$ and $x = -7$"},{"key":"B","text":"$x = -4$ and $x = 7$"},{"key":"C","text":"$x = 4$ and $x = 7$"},{"key":"D","text":"$x = -4$ and $x = -7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the quadratic: $x^2 + 3x - 28 = (x + 7)(x - 4) = 0$, so $x = -7$ or $x = 4$. The distractor $x = -4$ and $x = 7$ reverses the signs of both roots. The distractor $x = 4$ and $x = 7$ drops the negative sign from the larger root. The distractor $x = -4$ and $x = -7$ incorrectly makes both roots negative.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GEBORU', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'A line in the $xy$-plane has the equation $7x + 2y = 18$. What is the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{7}{2}$"},{"key":"B","text":"$\\frac{7}{2}$"},{"key":"C","text":"$-\\frac{2}{7}$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting in slope-intercept form: $2y = -7x + 18$, so $y = -\\frac{7}{2}x + 9$. The slope is $-\\frac{7}{2}$. The value $\\frac{7}{2}$ results from dropping the negative sign when isolating $y$. The value $-\\frac{2}{7}$ comes from taking the reciprocal of the slope, confusing it with the perpendicular slope. The value $9$ is the $y$-intercept, not the slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GM4BHC', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'The equation of line $p$ is $4x + 9y = 36$. Line $q$ is perpendicular to line $p$ and passes through the point $(-2, 5)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{4}$"},{"key":"B","text":"$\\frac{1}{2}$"},{"key":"C","text":"$\\frac{19}{2}$"},{"key":"D","text":"$-\\frac{19}{2}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewriting line $p$: $y = -\\frac{4}{9}x + 4$, so its slope is $-\\frac{4}{9}$. The perpendicular slope is $\\frac{9}{4}$. Using point $(-2, 5)$: $5 = \\frac{9}{4}(-2) + b$, giving $5 = -\\frac{9}{2} + b$, so $b = 5 + \\frac{9}{2} = \\frac{19}{2}$. The value $\\frac{9}{4}$ confuses the perpendicular slope with the $y$-intercept. The value $\\frac{1}{2}$ results from using the original slope $-\\frac{4}{9}$ instead of the perpendicular slope, yielding $5 = -\\frac{4}{9}(-2) + b = \\frac{8}{9} + b$, then miscalculating. The value $-\\frac{19}{2}$ comes from a sign error when adding $\\frac{9}{2}$ to $5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GQPLTB', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $7x^2 - 3x + 4x^2 + 9x - 2$?', NULL, $lyceon_json$[{"key":"A","text":"$11x^2 + 6x - 2$"},{"key":"B","text":"$11x^2 - 12x - 2$"},{"key":"C","text":"$3x^2 + 6x - 2$"},{"key":"D","text":"$11x^2 + 6x + 2$"}]$lyceon_json$::jsonb, 'A', NULL, E'Combine like terms: the $x^2$ terms give $7x^2 + 4x^2 = 11x^2$, the $x$ terms give $-3x + 9x = 6x$, and the constant is $-2$. The simplified expression is $11x^2 + 6x - 2$. The distractor $11x^2 - 12x - 2$ results from subtracting the $x$ coefficients as $-3 - 9 = -12$ instead of adding. The distractor $3x^2 + 6x - 2$ comes from subtracting the $x^2$ coefficients ($7 - 4$) instead of adding. The distractor $11x^2 + 6x + 2$ incorrectly treats the constant as $+2$ instead of $-2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GX8BU8', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A bookstore owner buys novels for $\\$7$ each and textbooks for $\\$13$ each. She wants to purchase at least $19$ books total while spending no more than $\\$181$. If $n$ represents the number of novels and $t$ represents the number of textbooks, which system of inequalities models this situation?', NULL, $lyceon_json$[{"key":"A","text":"$n + t \\geq 19$ and $7n + 13t \\leq 181$"},{"key":"B","text":"$n + t \\leq 19$ and $7n + 13t \\leq 181$"},{"key":"C","text":"$n + t \\geq 19$ and $7n + 13t \\geq 181$"},{"key":"D","text":"$n + t \\leq 19$ and $13n + 7t \\leq 181$"}]$lyceon_json$::jsonb, 'A', NULL, E'The owner wants at least $19$ books, so $n + t \\geq 19$. She wants to spend no more than $\\$181$, with novels at $\\$7$ and textbooks at $\\$13$, so $7n + 13t \\leq 181$. The option $n + t \\leq 19$ and $7n + 13t \\leq 181$ reverses the "at least" condition to "at most." The option $n + t \\geq 19$ and $7n + 13t \\geq 181$ reverses the budget constraint direction, requiring spending at least $\\$181$ instead of at most. The option $n + t \\leq 19$ and $13n + 7t \\leq 181$ both reverses the book-count inequality and swaps the per-unit costs of novels and textbooks.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HKD7M8', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $y$ in the solution to the system $x + y = 17$ and $x - y = 5$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$11$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations gives $2x = 22$, so $x = 11$. Substituting back into $x + y = 17$ gives $y = 6$. The value $11$ results from finding $x$ instead of $y$. The value $5$ results from confusing the constant in the second equation with the answer. The value $12$ comes from a sign error when subtracting to solve for $y$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HS6KL7', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'A plumber charges a $\\$53$ service fee plus $\\$29$ per hour of labor. If a customer''s total bill was $\\$198$, how many hours did the plumber work?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'The equation is $53 + 29h = 198$. Subtracting 53 from both sides gives $29h = 145$, and dividing by 29 gives $h = 5$. The value $7$ results from dividing the total bill by the hourly rate without subtracting the service fee ($198 \\div 29 \\approx 6.8$, rounded to $7$). The value $4$ comes from a subtraction error. The value $6$ results from misinterpreting the problem setup.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I3RRZC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If $\\sqrt{5x + 11} = x + 1$, what is the sum of all real solutions?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Square both sides: $5x + 11 = (x + 1)^2 = x^2 + 2x + 1$. Rearrange: $x^2 - 3x - 10 = 0$. Factor: $(x - 5)(x + 2) = 0$, giving $x = 5$ or $x = -2$. Check $x = 5$: $\\sqrt{5(5) + 11} = \\sqrt{36} = 6$ and $5 + 1 = 6$, which is valid. Check $x = -2$: $\\sqrt{5(-2) + 11} = \\sqrt{1} = 1$ and $-2 + 1 = -1$. Since $1 \\neq -1$, this solution is extraneous. Only $x = 5$ is a valid solution, so the sum of all real solutions is $5$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I9UE2J', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $\\frac{2x}{5} = 12$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$17$"},{"key":"C","text":"$30$"},{"key":"D","text":"$60$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiplying both sides by $5$ gives $2x = 60$, and dividing both sides by $2$ gives $x = 30$. The value $6$ results from dividing $12$ by $2$ without multiplying by $5$ first, confusing the order of operations. The value $17$ comes from adding $12 + 5$ instead of multiplying. The value $60$ results from multiplying $12 \\times 5 = 60$ but stopping before dividing by $2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J65Z3K', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 7x - 23$. What is the value of $f(11)$?', NULL, $lyceon_json$[{"key":"A","text":"$100$"},{"key":"B","text":"$77$"},{"key":"C","text":"$54$"},{"key":"D","text":"$-54$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 11$: $f(11) = 7(11) - 23 = 77 - 23 = 54$. The value $100$ results from adding $77 + 23$ instead of subtracting. The value $77$ comes from computing $7 \\times 11$ but not subtracting $23$. The value $-54$ results from a sign error, computing $23 - 77$ instead of $77 - 23$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JCAM0Z', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'The expression $\\frac{x^2 - 49}{x^2 + 10x + 21}$ is equivalent to which of the following for $x \\neq -3$ and $x \\neq -7$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 7}{x + 3}$"},{"key":"B","text":"$\\frac{x - 7}{x + 3}$"},{"key":"C","text":"$\\frac{x - 7}{x - 3}$"},{"key":"D","text":"$\\frac{x + 7}{x - 3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator as a difference of squares: $x^2 - 49 = (x - 7)(x + 7)$. Factor the denominator: $x^2 + 10x + 21 = (x + 3)(x + 7)$. Cancel the common factor $(x + 7)$ to obtain $\\frac{x - 7}{x + 3}$. The distractor $\\frac{x + 7}{x + 3}$ incorrectly cancels $(x - 7)$ instead of $(x + 7)$. The distractor $\\frac{x - 7}{x - 3}$ uses an incorrect sign in the denominator factor. The distractor $\\frac{x + 7}{x - 3}$ has errors in both the cancelled factor and the denominator sign.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KIOJV3', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The linear function $h$ satisfies $h(3) = 29$ and $h(11) = 53$. What is the value of $h(-5)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'The slope of $h$ is $\\frac{53 - 29}{11 - 3} = \\frac{24}{8} = 3$. Using the point $(3, 29)$: $29 = 3(3) + b$, so $b = 29 - 9 = 20$. Therefore $h(x) = 3x + 20$, and $h(-5) = 3(-5) + 20 = -15 + 20 = 5$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KZ1DY8', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'If $15 - 2x < 7$, which of the following could be the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$4$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'D', NULL, E'Subtracting $15$ from both sides gives $-2x < -8$. Dividing both sides by $-2$ and flipping the inequality sign gives $x > 4$. The value $5$ is the only option greater than $4$. The value $4$ results from treating the strict inequality $x > 4$ as though $4$ itself satisfies it. The values $2$ and $3$ are both less than $4$ and do not satisfy the inequality; choosing them reflects a misunderstanding of the direction when dividing by a negative number.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M9Z360', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive value of $x$ that satisfies $2x^2 - 50 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$25$"},{"key":"C","text":"$5\\sqrt{2}$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'A', NULL, E'Add 50 to both sides: $2x^2 = 50$. Divide by 2: $x^2 = 25$. Take the positive square root: $x = 5$. The distractor $25$ stops at $x^2 = 25$ and reports the value of $x^2$ rather than $x$. The distractor $5\\sqrt{2}$ computes $\\sqrt{50}$ instead of $\\sqrt{25}$, failing to divide by 2 before taking the root. The distractor $10$ incorrectly divides $50$ by $5$ instead of taking the square root of $25$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P7NBT9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A sphere has a volume of $288\\pi$ cubic centimeters. What is the surface area of the sphere, in square centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$24\\pi$"},{"key":"B","text":"$36\\pi$"},{"key":"C","text":"$144\\pi$"},{"key":"D","text":"$288\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'Set the volume formula equal to $288\\pi$: $\\frac{4}{3}\\pi r^3 = 288\\pi$. Dividing both sides by $\\pi$ gives $\\frac{4}{3}r^3 = 288$, so $r^3 = 216$ and $r = 6$. The surface area is $4\\pi r^2 = 4\\pi(36) = 144\\pi$. The value $24\\pi$ comes from computing $4\\pi r = 4\\pi(6)$, using the circumference-like expression instead of the area formula. The value $36\\pi$ equals $\\pi r^2 = \\pi(36)$, which omits the factor of $4$ in the surface area formula. The value $288\\pi$ simply restates the given volume rather than computing the surface area.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P9FFJW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = -3(x - 7)^2 + 41$ has a maximum value. What is the value of $x$ at which $h(x)$ reaches this maximum?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$7$"},{"key":"C","text":"$41$"},{"key":"D","text":"$-41$"}]$lyceon_json$::jsonb, 'B', NULL, E'The function $h(x) = -3(x - 7)^2 + 41$ is in vertex form $a(x - h)^2 + k$ with vertex at $(7, 41)$. Since $a = -3 < 0$, the parabola opens downward, and the vertex represents the maximum. The $x$-value at the maximum is $7$. The value $-7$ results from a sign error when reading $h$ from $(x - 7)$. The value $41$ is the maximum output value of the function, not the $x$-value where it occurs. The value $-41$ confuses both the sign and the role of the vertex coordinates.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PNOQ0O', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'The equation $ax + 3y = 21$ represents a line in the $xy$-plane that passes through the point $(6, 1)$. What is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$3$"},{"key":"C","text":"$6$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting the point $(6, 1)$ into the equation gives $6a + 3(1) = 21$, so $6a + 3 = 21$, which means $6a = 18$ and $a = 3$. The value $1$ results from confusing the $y$-coordinate of the given point with the answer. The value $6$ comes from computing $18 \\div a$ but mistakenly treating $6$ as the answer rather than the coefficient of $a$. The value $7$ results from dividing $21 \\div 3 = 7$ without accounting for the full substitution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S3SFG7', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = -3x + b$, where $b$ is a constant. If $g(7) = 19$, what is the value of $g(-4)$?', NULL, $lyceon_json$[{"key":"A","text":"$28$"},{"key":"B","text":"$40$"},{"key":"C","text":"$52$"},{"key":"D","text":"$-52$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $g(7) = -3(7) + b = -21 + b = 19$, it follows that $b = 40$. So $g(x) = -3x + 40$. Then $g(-4) = -3(-4) + 40 = 12 + 40 = 52$. The value $28$ results from computing $-3(-4)$ as $-12$ instead of $12$, giving $-12 + 40 = 28$. The value $40$ comes from finding $b$ but not evaluating $g(-4)$. The value $-52$ results from a sign error in the final calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SNRTJR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation $x^2 + y^2 + 14x - 4y - 11 = 0$ represents a circle in the $xy$-plane. What is the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{11}$"},{"key":"B","text":"$8$"},{"key":"C","text":"$\\sqrt{53}$"},{"key":"D","text":"$64$"}]$lyceon_json$::jsonb, 'B', NULL, E'Complete the square for each variable. Group the $x$-terms: $x^2 + 14x = (x + 7)^2 - 49$. Group the $y$-terms: $y^2 - 4y = (y - 2)^2 - 4$. Substituting: $(x + 7)^2 - 49 + (y - 2)^2 - 4 - 11 = 0$, so $(x + 7)^2 + (y - 2)^2 = 64$. Since $r^2 = 64$, the radius is $r = 8$. The value $\\sqrt{11}$ results from taking the square root of the constant $11$ without completing the square. The value $\\sqrt{53}$ comes from adding only $49 + 4 = 53$ but forgetting to include the constant $11$ on the right side. The value $64$ is $r^2$, not $r$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TRFRK9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one of the acute angles measures $\\theta$. If $\\sin(\\theta) = \\frac{5}{13}$, what is $\\cos(\\theta)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{12}$"},{"key":"B","text":"$\\frac{8}{13}$"},{"key":"C","text":"$\\frac{12}{13}$"},{"key":"D","text":"$\\frac{13}{12}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\sin(\\theta) = \\frac{5}{13}$, the side opposite $\\theta$ is $5$ and the hypotenuse is $13$. By the Pythagorean theorem, the adjacent side is $\\sqrt{13^2 - 5^2} = \\sqrt{169 - 25} = \\sqrt{144} = 12$. Therefore $\\cos(\\theta) = \\frac{12}{13}$. The value $\\frac{5}{12}$ is $\\tan(\\theta)$, not cosine. The value $\\frac{8}{13}$ arises from subtracting $13 - 5 = 8$ directly instead of using the Pythagorean theorem on the squares. The value $\\frac{13}{12}$ is $\\sec(\\theta)$, the reciprocal of cosine.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U532FL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'The number of registered voters in a district increased from $6{,}400$ to $7{,}296$. What is the percent increase?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'The increase is $7{,}296 - 6{,}400 = 896$. The percent increase is $\\frac{896}{6{,}400} \\times 100 = 14\\%$. A common error is dividing the increase by the new value ($\\frac{896}{7{,}296} \\approx 12.3\\%$) instead of the original value.', NULL, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2URIL9B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of $450$ residents of a city found that $63\\%$ support building a new park. The margin of error for this estimate is $\\pm 4\\%$. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $63\\%$ of all city residents support building the new park."},{"key":"B","text":"Between $59\\%$ and $67\\%$ of all city residents are likely to support building the new park."},{"key":"C","text":"Between $59\\%$ and $67\\%$ of the $450$ sampled residents support building the new park."},{"key":"D","text":"At most $67\\%$ of all city residents support building the new park."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of $\\pm 4\\%$ around a sample estimate of $63\\%$ produces a confidence interval from $59\\%$ to $67\\%$. This interval is an estimate for the entire population, not just the sample. The claim that exactly $63\\%$ of all residents support the park ignores the uncertainty captured by the margin of error. The claim about the sampled residents is incorrect because the margin of error applies to inferences about the population, not the sample itself. The claim that at most $67\\%$ support the park uses only the upper bound and ignores the lower bound of the interval.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VBTPOK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations $y = x^2 - 6x + c$ and $y = 2x - 7$ has exactly one solution. What is the value of $c$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$-9$"},{"key":"C","text":"$16$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Set the equations equal: $x^2 - 6x + c = 2x - 7$, which gives $x^2 - 8x + (c + 7) = 0$. For exactly one solution, the discriminant must equal zero: $(-8)^2 - 4(1)(c + 7) = 0$, so $64 - 4c - 28 = 0$, giving $36 = 4c$ and $c = 9$. The distractor $-9$ applies the wrong sign when solving for $c$. The distractor $16$ comes from setting $64 - 4c = 0$ and solving $c = 16$, forgetting the constant $+7$ in the rearranged equation. The distractor $7$ confuses the constant from the linear equation with the answer.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VKTKQW', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'If $4a + 3b = 37$ and $2a - 3b = 5$, what is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'Adding the two equations eliminates $b$: $(4a + 3b) + (2a - 3b) = 37 + 5$, which gives $6a = 42$, so $a = 7$. Substituting into $4(7) + 3b = 37$ gives $28 + 3b = 37$, so $3b = 9$ and $b = 3$. Therefore $a + b = 7 + 3 = 10$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VUYE6N', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A gym membership costs a one-time enrollment fee plus a fixed monthly rate. After 3 months of membership, the total amount paid is $\\$259$. After 8 months of membership, the total amount paid is $\\$479$. What is the monthly rate, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$\\$44$"},{"key":"B","text":"$\\$48$"},{"key":"C","text":"$\\$55$"},{"key":"D","text":"$\\$127$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $m$ be the monthly rate and $b$ the enrollment fee. Then $b + 3m = 259$ and $b + 8m = 479$. Subtracting the first equation from the second gives $5m = 220$, so $m = 44$. The monthly rate is $\\$44$. The value $\\$48$ results from an arithmetic error when dividing $220$ by $5$. The value $\\$55$ comes from incorrectly setting up the subtraction as $8m - 3m = 479 - 259 \\div 4$. The value $\\$127$ confuses the enrollment fee ($259 - 3(44) = 127$) with the monthly rate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W0IRM4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'An exponential function is defined as $p(t) = 250 \\cdot 3^t$. What is the value of $p(4)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '20250', ARRAY['20250'], E'Substituting $t = 4$ into $p(t) = 250 \\cdot 3^t$ gives $p(4) = 250 \\cdot 3^4 = 250 \\cdot 81 = 20250$. The computation requires evaluating $3^4 = 81$ and then multiplying by $250$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WLGXML', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'Line $l$ has equation $5x - 2y = 16$. Line $m$ is parallel to line $l$ and passes through the point $(4, 9)$. What is the $y$-intercept of line $m$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-1', ARRAY['-1'], E'Rewriting line $l$ in slope-intercept form: $y = \\frac{5}{2}x - 8$, so the slope is $\\frac{5}{2}$. Since line $m$ is parallel, it has the same slope. Using the point $(4, 9)$: $9 = \\frac{5}{2}(4) + b$, which gives $9 = 10 + b$, so $b = -1$. The $y$-intercept of line $m$ is $-1$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X2PUEF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'If $f(x) = 7x^2 - 3x + 11$, what is the value of $f(-3)$?', NULL, $lyceon_json$[{"key":"A","text":"$83$"},{"key":"B","text":"$47$"},{"key":"C","text":"$65$"},{"key":"D","text":"$74$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = -3$: $f(-3) = 7(-3)^2 - 3(-3) + 11 = 7(9) + 9 + 11 = 63 + 9 + 11 = 83$. The value $47$ results from substituting the squared value $9$ for $x$ in the linear term as well, computing $7(9) - 3(9) + 11 = 63 - 27 + 11 = 47$. The value $65$ results from a sign error in the linear term, computing $-3(-3)$ as $-9$ instead of $+9$, yielding $63 - 9 + 11 = 65$. The value $74$ results from omitting the linear term entirely, computing $7(9) + 11 = 74$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y7627E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A recipe calls for $11$ cups of oats for every $4$ cups of honey. If a chef uses $12$ cups of honey, how many cups of oats does the chef need?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '33', ARRAY['33'], E'The ratio of oats to honey is $\\frac{11}{4}$. To find the cups of oats needed for $12$ cups of honey, multiply: $\\frac{11}{4} \\times 12 = \\frac{132}{4} = 33$. The correct answer is $33$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZCD8JN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a survey of $200$ employees at a company, $85$ work remotely and $115$ work on-site. Of the remote workers, $34$ have a graduate degree. Of the on-site workers, $23$ have a graduate degree. If one employee is selected at random from those who have a graduate degree, what is the probability that the selected employee works remotely?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{34}{200}$"},{"key":"B","text":"$\\frac{34}{85}$"},{"key":"C","text":"$\\frac{34}{57}$"},{"key":"D","text":"$\\frac{57}{200}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of employees with a graduate degree is $34 + 23 = 57$. Since the selection is made from employees with a graduate degree, the probability that the selected employee works remotely is $\\frac{34}{57}$. The fraction $\\frac{34}{200}$ incorrectly uses the total number of employees as the denominator instead of restricting to those with a graduate degree. The fraction $\\frac{34}{85}$ uses the total number of remote workers as the denominator, which would give the probability that a randomly selected remote worker has a graduate degree. The fraction $\\frac{57}{200}$ gives the probability that a randomly selected employee has a graduate degree, not the conditional probability asked for.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21YCVE1', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Sociologist Arlie Russell Hochschild coined the term "emotional labor" in 1983 to describe the process by which workers in service industries manage their outward emotional displays to fulfill job requirements. Flight attendants, for example, must project warmth and calm even during turbulent conditions or confrontational interactions with passengers. Over subsequent decades, however, the concept migrated well beyond its original scope: popular usage now applies "emotional labor" to unpaid domestic tasks, interpersonal caregiving, and the mental burden of managing household logistics. Hochschild herself has expressed concern that this expanded usage dilutes the term''s analytical precision, obscuring the specific power dynamics between employers and employees that her original research was designed to illuminate.', $lyceon_json$[{"key":"A","text":"It defines a specialized term, illustrates its original application, traces its expansion into broader usage, and then presents the originator's critique of that expansion."},{"key":"B","text":"It proposes a new sociological theory, tests it against empirical data from the airline industry, and concludes that the theory is only partially supported."},{"key":"C","text":"It contrasts two competing definitions of a concept and argues that both are equally valid when applied to different social contexts."},{"key":"D","text":"It describes a workplace phenomenon, attributes it to institutional negligence, and recommends specific policy reforms to address it."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first defines "emotional labor" as Hochschild coined it, then illustrates it with the flight attendant example, then describes how popular usage expanded the term, and finally presents Hochschild''s critique that this expansion dilutes analytical precision. The option tracing definition, illustration, expansion, and critique accurately mirrors this four-part structure. The option about proposing and testing a theory against airline data is wrong because the passage is about conceptual drift of a term, not empirical testing of a hypothesis. The option about contrasting two equally valid definitions is wrong because the passage presents Hochschild as critical of the expanded usage, not as endorsing both definitions. The option about attributing a phenomenon to institutional negligence and recommending reforms is wrong because the passage discusses the evolution of a concept, not policy recommendations or institutional blame.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22S7J0K', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1: Musicologist Elaine Sisman has argued that Beethoven''s late string quartets deliberately fracture the formal expectations established by Haydn and Mozart, using abrupt key changes and asymmetric phrase lengths to create a sense of psychological dislocation in the listener. Sisman interprets these structural disruptions as expressions of Beethoven''s increasingly isolated personal circumstances during the final decade of his life.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23EK00Q', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Svalbard Global Seed Vault, a facility carved into the permafrost of a Norwegian Arctic ______ stores duplicate samples of seeds from gene banks worldwide, serving as a backup in case regional collections are lost to natural disasters, armed conflicts, or equipment failures.', $lyceon_json$[{"key":"A","text":"mountainside; stores"},{"key":"B","text":"mountainside stores"},{"key":"C","text":"mountainside, stores"},{"key":"D","text":"mountainside—stores"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is "mountainside, stores" because the phrase "a facility carved into the permafrost of a Norwegian Arctic mountainside" is a nonrestrictive appositive renaming "The Svalbard Global Seed Vault." Since the appositive is opened with a comma after "Vault," it must be closed with a matching comma before the main verb "stores" resumes the sentence. The choice "mountainside; stores" is incorrect because a semicolon would split the sentence into two parts, but the segment before the semicolon ("The Svalbard Global Seed Vault, a facility carved into the permafrost of a Norwegian Arctic mountainside") is a noun phrase with no main verb and therefore cannot function as an independent clause. The choice "mountainside stores" omits the closing comma of the appositive, causing the reader to misparse "mountainside stores" as a compound noun rather than a boundary between the appositive and the main verb. The choice with an em dash is incorrect because the appositive was opened with a comma; paired punctuation must be consistent, and mixing a comma with an em dash violates that convention.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW274WBWK', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how does the framework presented in Text 2 complicate the conclusion drawn in Text 1?', E'Text 1: A 2023 study by epidemiologists at the Karolinska Institute tracked 14,000 Swedish adults over eleven years and found that individuals who reported eating home-cooked meals at least five times per week had a 23 percent lower incidence of type 2 diabetes than those who relied primarily on restaurant or pre-prepared meals. The researchers concluded that home cooking confers a direct metabolic benefit, likely through lower caloric density and reduced sodium and added sugar content in home-prepared dishes.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28PJRKO', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'During the late nineteenth century, the Brazilian government actively encouraged European immigration to the southern state of Rio Grande do Sul, offering subsidized land grants to families willing to establish small farms in sparsely populated highland areas. Government officials expected these settlers to replicate the intensive small-plot agriculture practiced in their countries of origin. However, many immigrant families instead adopted extensive cattle ranching within a generation of arrival, despite having no prior experience with livestock on that scale. Historians examining land-use records from the period have noted that the highland plots allocated to immigrants, averaging 77 hectares, were substantially larger than typical European smallholdings, which rarely exceeded 11 hectares. This discrepancy suggests that the settlers'' shift to ranching ________', $lyceon_json$[{"key":"A","text":"was driven partly by the impracticality of applying intensive cultivation methods to landholdings far larger than those for which such methods were designed"},{"key":"B","text":"reflected a deliberate government strategy to convert the southern highlands from subsistence farming into an export-oriented livestock economy"},{"key":"C","text":"occurred because the settlers had received formal agricultural training from Brazilian ranchers before taking possession of their allocated plots"},{"key":"D","text":"resulted primarily from the settlers' cultural preference for pastoral over agricultural livelihoods, a preference they had suppressed in Europe due to limited land"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that the allocated plots were about seven times larger than typical European smallholdings and that the government expected settlers to practice intensive small-plot agriculture. The logical inference from this size discrepancy is that the settlers shifted to ranching partly because intensive cultivation methods were impractical on such large parcels. The choice about a deliberate government strategy contradicts the passage, which states the government expected small-plot agriculture, not ranching. The choice about formal training from Brazilian ranchers introduces information absent from the passage, which says the settlers had no prior experience with large-scale livestock. The choice about suppressed cultural preferences for pastoral livelihoods speculates about psychological motivations the passage does not address and contradicts the stated lack of prior ranching experience.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28R4Z27', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to contrast the two proposed explanations for the high iron content in Martian regolith. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BYN471', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When selecting nesting sites, the rufous hornero evaluates several environmental ______ proximity to a reliable water source, availability of clay-rich mud for construction, and the presence of sturdy branches capable of supporting a nest weighing up to five kilograms.', $lyceon_json$[{"key":"A","text":"factors, proximity"},{"key":"B","text":"factors: proximity"},{"key":"C","text":"factors; proximity"},{"key":"D","text":"factors proximity"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "factors: proximity" because a colon is the appropriate punctuation after a complete independent clause that introduces a list. The clause "the rufous hornero evaluates several environmental factors" is a complete thought, and the items that follow (proximity to water, availability of mud, and presence of branches) specify what those factors are. The choice "factors, proximity" is incorrect because a comma cannot properly introduce a list after an independent clause; it creates ambiguity about whether "proximity" is another item parallel to "factors" or the start of the explanatory list. The choice "factors; proximity" is wrong because a semicolon requires two independent clauses, and "proximity to a reliable water source, availability of clay-rich mud..." is a series of noun phrases, not an independent clause. The choice "factors proximity" omits necessary punctuation entirely, creating a run-on.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D813JU', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Neuroscientist Aris Thanopoulos investigated whether the human brain processes moral judgments about actions and moral judgments about outcomes through the same neural pathway. He used functional MRI to scan participants while they evaluated scenarios in which an agent''s intention and the resulting outcome were either aligned (good intention, good outcome) or misaligned (good intention, bad outcome). Thanopoulos found that judgments about intentions consistently activated the right temporoparietal junction, a region associated with mental-state attribution, whereas judgments about outcomes activated the ventromedial prefrontal cortex, a region linked to value computation. Crucially, when intention and outcome conflicted, neither region showed suppressed activity; instead, both regions activated simultaneously at levels comparable to their respective non-conflict conditions. This simultaneous activation pattern suggests that ________', $lyceon_json$[{"key":"A","text":"moral evaluation of conflicting scenarios engages both neural pathways independently rather than routing through a single integrative mechanism"},{"key":"B","text":"the right temporoparietal junction is primarily responsible for producing the final moral judgment across all experimental scenarios, while the ventromedial prefrontal cortex plays only a secondary modulatory role during conflict processing"},{"key":"C","text":"participants found the misaligned scenarios significantly more cognitively demanding than the aligned scenarios, as reflected in longer response times and higher self-reported difficulty ratings"},{"key":"D","text":"moral judgments about intentions are formed earlier in the neural processing sequence than judgments about outcomes, and the two are integrated only at a late decision stage"}]$lyceon_json$::jsonb, 'A', NULL, E'The key finding is that during conflicting scenarios, both brain regions activated simultaneously at levels comparable to non-conflict conditions, with neither showing suppression. This pattern most logically supports the inference that the two pathways operate independently rather than feeding into a single integrative mechanism that would suppress one in favor of the other. The choice claiming the right temporoparietal junction produces the final judgment while the ventromedial prefrontal cortex merely modulates contradicts the finding that both regions activated at comparable levels without suppression. The choice about cognitive demand and response times introduces behavioral measures the passage never mentions; the passage reports only neural activation patterns. The choice about sequential processing and late-stage integration speculates about temporal ordering that the passage does not address, since fMRI measures activation location and intensity, not the precise timing sequence of neural events.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DXBDCW', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Certain species of Antarctic tardigrades can survive temperatures as low as negative 196 degrees Celsius by entering a state called cryptobiosis, in which their metabolic activity drops to nearly undetectable levels. During cryptobiosis, the organisms produce a sugar called trehalose that replaces water in their cells, forming a glass-like matrix that prevents ice crystals from damaging cellular structures. Once conditions become favorable again, the tardigrades rehydrate and resume normal biological functions within hours, showing no lasting impairment from their frozen state.', $lyceon_json$[{"key":"A","text":"Tardigrades survive extreme cold by entering cryptobiosis, which protects their cells through trehalose production and allows full recovery"},{"key":"B","text":"Trehalose is a sugar that forms a protective glass-like matrix inside cells exposed to subzero environments, and scientists have studied its role in preserving biological tissue"},{"key":"C","text":"Antarctic organisms have evolved numerous chemical defenses against freezing that scientists are only beginning to catalog comprehensively in controlled laboratory settings"},{"key":"D","text":"The metabolic activity of tardigrades is nearly undetectable during prolonged exposure to laboratory freezing conditions"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how tardigrades survive extreme cold through cryptobiosis and trehalose production, then recover fully when conditions improve. The choice stating that tardigrades survive extreme cold through cryptobiosis and trehalose-mediated cell protection, with full recovery, captures all three key elements of the passage. The choice focusing on trehalose and its glass-like matrix addresses a supporting detail rather than the overall idea. The choice about numerous chemical defenses across Antarctic organisms goes beyond what the passage states, which discusses only tardigrades and only trehalose. The choice about undetectable metabolic activity in laboratory conditions misrepresents a detail: the passage mentions cryptobiosis generally, not specifically prolonged laboratory exposure.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FSNO44', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'A team of marine biologists led by Kenji Furukawa hypothesized that the bioluminescent displays of the firefly squid Watasenia scintillans serve primarily as a predator-confusion mechanism rather than as a mate-attraction signal. The researchers noted that the squid''s light-producing photophores are distributed across the ventral surface in a pattern that, when activated, disrupts the animal''s silhouette as seen from below. If the displays function mainly to confuse predators approaching from beneath, the researchers predicted that specific observable patterns would distinguish this function from courtship signaling.', $lyceon_json$[{"key":"A","text":"Firefly squid activate their ventral photophores at similar rates regardless of whether potential mates are nearby or absent"},{"key":"B","text":"The wavelengths produced by firefly squid photophores closely match the ambient light filtering down from the ocean surface during daylight hours"},{"key":"C","text":"Firefly squid in aquarium settings display bioluminescence less frequently than those observed in open-ocean environments with natural predators present"},{"key":"D","text":"Several other squid species in the same habitat also possess ventral photophores but use them exclusively during their annual reproductive displays each spring"}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis is that bioluminescent displays serve predator confusion rather than mate attraction. If the squid activate ventral photophores at similar rates whether or not potential mates are present, that directly undermines the mate-attraction explanation and supports the predator-confusion function. The finding about wavelength matching ambient light relates to counterillumination camouflage, which is a related but distinct concept from the active predator-confusion mechanism described. The finding about reduced bioluminescence in aquariums could have multiple explanations, including stress or altered behavior, and does not directly distinguish between the two proposed functions. The finding about other squid species using photophores for reproduction addresses different organisms and does not bear on whether firefly squid displays serve predator confusion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FSRLYL', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1980, physicist Luis Alvarez and his son, geologist Walter Alvarez, published a paper that would transform the field of paleontology. The Alvarez ______ which proposed that a massive asteroid impact caused the extinction of non-avian dinosaurs approximately 66 million years ago, initially faced considerable skepticism from paleontologists who favored volcanic explanations.', $lyceon_json$[{"key":"A","text":"hypothesis, which"},{"key":"B","text":"hypothesis. Which"},{"key":"C","text":"hypothesis; which"},{"key":"D","text":"hypothesis which"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is "hypothesis, which" because the clause "which proposed that a massive asteroid impact caused the extinction of non-avian dinosaurs approximately 66 million years ago" is a nonrestrictive relative clause providing additional information about the already-identified Alvarez hypothesis. Nonrestrictive clauses must be set off by commas, and the closing comma already appears after "ago" in the passage, so a comma must open the clause as well. The choice "hypothesis. Which" creates a sentence fragment because "Which proposed..." cannot stand alone as a sentence. Similarly, "hypothesis; which" is incorrect because a semicolon must join two independent clauses, and a clause beginning with "which" is dependent. The choice "hypothesis which" omits the necessary comma before a nonrestrictive clause, violating Standard English punctuation conventions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HCWY7R', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Kenji Ota observed that juvenile green sea turtles in Moreton Bay, Australia, prefer seagrass beds with high nitrogen content for foraging. ______ the turtles consistently bypassed nearby patches of low-nitrogen seagrass even when those patches were closer to their resting sites.', $lyceon_json$[{"key":"A","text":"In fact,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Meanwhile,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'The first sentence states that juvenile turtles prefer high-nitrogen seagrass beds. The second sentence reinforces that preference by providing a specific supporting detail: the turtles bypassed closer, low-nitrogen patches. "In fact" correctly signals that the second sentence intensifies or confirms the claim in the first. "In contrast" signals an opposing idea, but bypassing low-nitrogen patches is consistent with preferring high-nitrogen ones. "Meanwhile" signals simultaneous but unrelated events, yet the bypassing behavior directly relates to the nitrogen preference. "Consequently" signals a causal outcome, but the turtles'' bypassing behavior is an illustration of their preference, not a consequence of it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J355M4', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit fly Drosophila melanogaster can detect and avoid food sources contaminated with harmful bacteria. Researchers found that flies possess gustatory receptors on their legs that respond to lipopolysaccharides, molecules found on the outer membranes of many pathogenic bacteria. When these receptors are activated, the flies exhibit a characteristic leg-retraction behavior and move away from the contaminated surface. Flies in which these specific gustatory receptors were genetically disabled, however, showed no aversion to bacteria-laden food and consumed it at the same rate as uncontaminated food. This suggests that the flies'' avoidance behavior ________', $lyceon_json$[{"key":"A","text":"depends on the gustatory receptors rather than on visual or olfactory detection of bacterial contamination"},{"key":"B","text":"is a learned response acquired through repeated exposure to contaminated food sources in laboratory conditions"},{"key":"C","text":"occurs only when the bacterial concentration exceeds a specific threshold that varies with the fly's age and nutritional state"},{"key":"D","text":"has evolved independently in several Drosophila species found across diverse ecological habitats worldwide"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes an experiment in which disabling specific gustatory receptors eliminated avoidance behavior, while flies with intact receptors avoided contaminated food. This directly supports the inference that avoidance depends on those gustatory receptors rather than other sensory modalities. The choice about learned behavior contradicts the experimental design, which used genetic disabling rather than experiential conditioning. The choice about concentration thresholds varying with age and nutritional state introduces variables the passage never discusses. The choice about independent evolution across Drosophila species goes far beyond the evidence presented, which concerns only one species and one receptor mechanism.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L298OC', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Philosopher of science Hasok Chang has argued that abandoned scientific theories often retain explanatory value that their successors lack. The phlogiston theory, for example, offered an intuitive account of why metals gain a powdery residue when heated, an observation that early oxygen theory could address only through ______ reasoning involving invisible mass changes. Chang suggests that selectively recovering insights from discarded frameworks can enrich contemporary scientific understanding.', $lyceon_json$[{"key":"A","text":"circuitous"},{"key":"B","text":"melodramatic"},{"key":"C","text":"prophetic"},{"key":"D","text":"nostalgic for pre-industrial methods of"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts phlogiston theory''s intuitive explanation with early oxygen theory''s less direct treatment of the same observation, involving invisible mass changes. "Circuitous" means indirect or roundabout, which captures the idea that oxygen theory required a more complicated path to explain the phenomenon. "Melodramatic" means excessively emotional or theatrical, which is incoherent when describing scientific reasoning. "Prophetic" means predicting the future, which does not relate to the difficulty of explaining a present observation. "Nostalgic for pre-industrial methods of" introduces a sentimental attitude toward the past that the passage never suggests and produces a grammatically awkward construction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NC870A', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'A 2022 analysis by dendrochronologist Valerie Trouet revealed that a cluster of unusually narrow tree rings in Scandinavian pines corresponded precisely to the period of the Laki volcanic eruption in 1783. While historians had documented the eruption''s immediate effects on Icelandic agriculture, Trouet''s data ______ the event''s climatic reach, demonstrating that sulfur aerosols from the eruption suppressed tree growth across a far wider geographic band than contemporary accounts had recorded.', $lyceon_json$[{"key":"A","text":"attested to the full geographical scope of"},{"key":"B","text":"underscored"},{"key":"C","text":"trivialized"},{"key":"D","text":"fabricated"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explains that Trouet''s data demonstrated the eruption''s climatic effects reached farther than previously known, thereby emphasizing or highlighting the event''s broad reach. "Underscored" means to emphasize or highlight, which fits the passage''s point that the data revealed the eruption''s extensive climatic impact. "Attested to the full geographical scope of" implies the data merely confirmed a scope already known, but the passage states the data revealed an extent wider than contemporary accounts had recorded, making the data revelatory rather than confirmatory. "Trivialized" means to make something seem less important, which is the opposite of what the data did. "Fabricated" means to invent or falsify, which contradicts the passage''s presentation of the data as genuine scientific evidence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NDIHU1', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Paleontologist Adaora Nwachukwu''s 2022 excavation of a late Cretaceous fossil bed in Niger uncovered seventeen specimens of Nigersaurus taqueti with unusually worn dental batteries, suggesting that the sauropod fed on abrasive ground-level vegetation rather than softer canopy foliage. ______ isotopic analysis of the enamel conducted by geochemist Lars Hedlund in 2024 revealed carbon signatures consistent with fern and horsetail consumption, corroborating the hypothesis that Nigersaurus was a low-browsing specialist.', $lyceon_json$[{"key":"A","text":"For example,"},{"key":"B","text":"Regardless,"},{"key":"C","text":"Supporting this interpretation,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'C', NULL, E'Nwachukwu''s dental wear evidence suggested low-browsing behavior. Hedlund''s isotopic analysis independently found carbon signatures matching ferns and horsetails, which are ground-level plants. The second finding provides additional evidence for the same hypothesis, so "Supporting this interpretation" correctly signals that the isotopic data reinforces the dental wear conclusion. "For example" would introduce an illustrative instance of the claim, but Hedlund''s study is an independent line of evidence, not an example of dental wear. "Regardless" signals that the second point holds despite the first, implying tension that does not exist between two aligned findings. "In other words" signals a restatement of the same idea, but the isotopic analysis introduces new, distinct evidence rather than rephrasing the dental observation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OHFF8J', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Archaeobotanist Dorian Fuller has proposed that rice cultivation in the Yangtze River delta underwent a prolonged, uneven transition from wild harvesting to deliberate planting, spanning roughly three thousand years. Early sites in the region show mixtures of wild and cultivated rice grains in proportions that fluctuated dramatically across centuries, suggesting that communities intermittently reverted to foraging when experimental planting failed. <u>Fuller notes that this pattern of fitful adoption contrasts sharply with the Fertile Crescent model, in which wheat and barley cultivation appears to have progressed along a comparatively steady trajectory once initiated.</u> By foregrounding this contrast, Fuller challenges the assumption that agricultural origins followed a universal sequence, arguing instead that each domestication event must be understood within its own ecological and cultural constraints.', $lyceon_json$[{"key":"A","text":"It draws a comparison with another region's agricultural history to establish the distinctiveness of the pattern Fuller has described, which the final sentence then uses to support a broader theoretical claim."},{"key":"B","text":"It concedes that the evidence from the Yangtze delta is less reliable than the evidence from the Fertile Crescent, weakening the passage's central argument."},{"key":"C","text":"It provides a chronological summary of wheat domestication in the Fertile Crescent that serves as background for the Yangtze delta findings discussed earlier."},{"key":"D","text":"It introduces an objection from scholars who study Middle Eastern agriculture and who dispute Fuller's interpretation of the Yangtze evidence."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence contrasts the Yangtze delta''s fitful adoption pattern with the Fertile Crescent''s steady trajectory. The final sentence then uses this contrast to argue against a universal sequence of agricultural origins. The option about drawing a comparison to establish distinctiveness, which the final sentence extends into a broader claim, accurately captures this two-step function. The option about conceding that Yangtze evidence is less reliable is wrong because Fuller presents the contrast to highlight different patterns, not to undermine his own data. The option about providing a chronological summary of wheat domestication is wrong because the sentence offers only a brief characterization of the Fertile Crescent pattern, not a detailed chronology, and its purpose is comparative, not expository. The option about introducing an objection from Middle Eastern scholars is wrong because the sentence presents Fuller''s own observation, not a challenge from other researchers.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PI7O8A', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In the 1930s, mathematician Lothar Collatz proposed what became one of number theory''s most stubbornly unsolved problems. The conjecture states that for any positive integer, repeatedly applying a simple rule -- halving even numbers and tripling-then-adding-one to odd numbers -- will eventually reach the value one. Despite its elementary formulation, the conjecture has resisted proof for nearly a century. In 2019, Terence Tao demonstrated that almost all positive integers do eventually reach values very close to one, a result widely celebrated yet still falling short of a complete proof. The gap between Tao''s probabilistic near-certainty and absolute mathematical proof illustrates a persistent tension in number theory between computational evidence and formal demonstration.', $lyceon_json$[{"key":"A","text":"Tao's 2019 result proved that the Collatz conjecture holds for most integers but left open whether certain exceptions exist among very large numbers"},{"key":"B","text":"The Collatz conjecture, despite its simple formulation, remains unproven, and even a major recent advance highlights the gap between strong evidence and complete proof"},{"key":"C","text":"Simple-seeming mathematical conjectures are often the hardest to resolve because they resist standard proof techniques developed for more complex problems"},{"key":"D","text":"Number theorists have largely abandoned efforts to prove the Collatz conjecture after Tao's work showed that a complete proof would require entirely new mathematical frameworks"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage presents the Collatz conjecture as a simple yet unresolved problem and uses Tao''s 2019 result to illustrate the gap between probabilistic evidence and complete proof. The choice identifying both the conjecture''s simplicity-versus-difficulty contrast and the evidence-versus-proof tension captures the full scope of the passage. The choice about Tao proving the conjecture for most integers misrepresents his result: he showed integers reach values close to one, not that the conjecture holds for most integers, and the passage does not mention exceptions among large numbers. The choice about simple conjectures resisting standard proof techniques generalizes beyond what the passage discusses, which focuses only on the Collatz conjecture. The choice claiming number theorists have abandoned the problem contradicts the passage, which says nothing about abandonment or the need for new frameworks.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PIACD8', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'The student wants to identify the primary material used in Bhutanese traditional architecture. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QNBWCY', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'The student wants to argue that the conventional interpretation of Eli Pettersen''s 1923 experiments may be flawed because it overlooks a confounding variable. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SUWPVD', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Historian Mariana Ledesma has challenged the prevailing view that the decline of the Wari Empire in the eleventh century resulted primarily from prolonged drought. Ledesma acknowledges that paleoclimate records from lake sediments in the Ayacucho Basin confirm a drying trend between 1000 and 1100 CE. However, she points out that several Wari administrative centers in the Moquegua Valley -- a region that experienced comparable aridity -- continued to function for at least seventy years after centers in the heartland were abandoned. Ledesma argues that this disparity suggests internal political fragmentation, rather than environmental stress alone, drove the empire''s collapse, since uniform climate pressure would have produced a more synchronous pattern of abandonment across regions.', $lyceon_json$[{"key":"A","text":"Ledesma contends that political fragmentation better explains the Wari collapse than drought alone, because drought-affected regions declined at different rates rather than simultaneously"},{"key":"B","text":"Paleoclimate data from the Ayacucho Basin have confirmed that the Wari heartland experienced a severe drying trend between 1000 and 1100 CE that contributed significantly to urban abandonment"},{"key":"C","text":"The Moquegua Valley's Wari centers survived longer than heartland centers because the valley had access to irrigation systems that partially offset the effects of regional drought conditions"},{"key":"D","text":"Ledesma rejects the drought hypothesis entirely, proposing instead that elite power struggles within the Wari administrative hierarchy precipitated a rapid and coordinated imperial withdrawal from outlying provinces"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Ledesma''s argument that the asynchronous pattern of Wari center abandonment across regions experiencing similar drought points to political fragmentation rather than climate alone. The choice identifying Ledesma''s claim that political fragmentation better explains the collapse because drought-affected regions declined at different rates captures this central argument. The choice about paleoclimate data confirming a drying trend addresses only the evidence Ledesma acknowledges, not her argument about what that evidence means. The choice about irrigation systems in the Moquegua Valley introduces an explanation the passage never mentions. The choice stating Ledesma rejects the drought hypothesis entirely overstates her position: she acknowledges the drought evidence but argues it is insufficient as a sole explanation, not that it played no role.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T5IRE3', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Fatou Diagne has argued that cooperative land-tenure arrangements in the Senegal River Valley increase crop yields because shared irrigation infrastructure reduces per-farmer maintenance costs. Her 2021 field data showed that cooperatively managed plots produced 37 percent more millet per hectare than individually managed plots in the same watershed. ______ Diagne acknowledges that a disproportionate share of the yield gains accrued to farmers whose plots bordered the main canal, suggesting that the cooperative model''s benefits may depend heavily on a member''s position within the irrigation network rather than on cooperative membership alone.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"That said,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"For this reason,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first two sentences present Diagne''s argument and supporting data showing cooperative plots outperformed individual ones. The final sentence introduces a qualification: the gains were unevenly distributed and may depend on canal proximity rather than cooperation itself. "That said" correctly signals a concession or caveat that complicates the preceding positive finding. "Furthermore" signals additional supporting evidence, but the sentence introduces a limitation, not further support. "Specifically" signals a narrower elaboration of the preceding point, but the sentence shifts from affirming the yield advantage to questioning its underlying cause. "For this reason" signals a logical consequence of the yield data, but Diagne''s acknowledgment of uneven distribution qualifies rather than follows from the 37 percent advantage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TNV31E', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the explanation offered by Okonkwo and Petersen?', E'Behavioral ecologists Chidi Okonkwo and Lena Petersen proposed that the unusually high nest-site fidelity observed in the Eleonora''s falcon -- which breeds exclusively on Mediterranean sea cliffs and returns to the same ledge year after year -- is maintained primarily by the energetic advantages of site familiarity. They argued that returning falcons expend significantly less energy on territorial defense and nest preparation because they have already mapped the microhabitat''s wind patterns, food-caching locations, and predator approach routes. This efficiency gain, they claimed, outweighs the potential genetic benefits of dispersing to new sites, particularly for a species whose compressed late-summer breeding season leaves little margin for exploratory behavior.', $lyceon_json$[{"key":"A","text":"Falcons that were experimentally relocated to unfamiliar but structurally similar cliff ledges showed no measurable increase in energy expenditure during territorial defense or nest preparation compared to control falcons returning to familiar sites"},{"key":"B","text":"Eleonora's falcons that returned to previously used ledges arrived at breeding colonies an average of nine days earlier than falcons occupying a ledge for the first time, a difference consistent across seven consecutive breeding seasons"},{"key":"C","text":"Genetic analyses of Eleonora's falcon populations across fourteen Mediterranean colonies revealed low levels of inbreeding despite the species' high nest-site fidelity, suggesting that mate selection rather than site dispersal maintains genetic diversity"},{"key":"D","text":"Satellite tracking data showed that Eleonora's falcons undertake significantly longer foraging flights during the first week after arriving at breeding sites than during subsequent weeks, regardless of whether the site was previously occupied"}]$lyceon_json$::jsonb, 'A', NULL, E'Okonkwo and Petersen''s explanation rests on the claim that site familiarity provides an energetic advantage in territorial defense and nest preparation. The finding that relocated falcons showed no increase in energy expenditure at unfamiliar but structurally similar sites directly contradicts this claim, because it demonstrates that the predicted energetic cost of unfamiliarity does not materialize. The finding about earlier arrival at familiar ledges is consistent with site fidelity but does not address the energetic mechanism Okonkwo and Petersen proposed. The finding about low inbreeding despite high fidelity addresses a genetic consequence of the behavior pattern but does not challenge the energetic explanation for why fidelity is maintained. The finding about longer foraging flights during the first week relates to foraging rather than territorial defense or nest preparation, and it applies equally to familiar and unfamiliar sites, so it does not distinguish between the two conditions central to the hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U08JAF', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'In the early 2000s, entomologist Phil DeVries proposed that certain butterfly species in Costa Rican cloud forests rely on acoustic signals to communicate with ant colonies whose nests they parasitize. <u>DeVries recorded low-frequency vibrations produced by butterfly larvae and demonstrated that these vibrations closely mimicked the stridulation patterns of the host ant queen.</u> His findings indicated that the larvae exploit the ants'' own communication system to gain acceptance into the colony, where they feed on ant brood without provoking defensive behavior.', $lyceon_json$[{"key":"A","text":"It presents the experimental evidence that supports the hypothesis introduced in the preceding sentence."},{"key":"B","text":"It raises a methodological objection to the research program described elsewhere in the text."},{"key":"C","text":"It introduces a new hypothesis about butterfly migration patterns that the rest of the text goes on to evaluate."},{"key":"D","text":"It summarizes the overall conclusion of the passage in a single condensed statement about acoustic mimicry."}]$lyceon_json$::jsonb, 'A', NULL, E'The preceding sentence introduces DeVries''s proposal that certain butterflies use acoustic signals to communicate with ant colonies. The underlined sentence then describes his recordings and demonstrations that larvae vibrations mimicked ant queen stridulation, providing the experimental basis for his proposal. The option about presenting experimental evidence supporting the hypothesis captures this function. The option about raising a methodological objection is wrong because the sentence describes evidence in favor of the hypothesis, not a challenge to it. The option about introducing a new hypothesis about migration is wrong because the sentence concerns acoustic mimicry within ant nests, not butterfly migration. The option about summarizing the overall conclusion is wrong because the sentence provides specific evidence rather than condensing the passage''s conclusion; the final sentence states the broader implication.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VD3QWB', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a research article would best support the claim that urban tree canopy coverage reduces residential energy consumption?', E'Municipal planners in several mid-latitude cities have increasingly advocated for expanding urban tree canopy as a strategy to lower household energy costs. Proponents argue that strategically planted deciduous trees on the south and west sides of residential buildings provide shade that reduces cooling demand in summer while allowing solar heating in winter after leaf drop. Critics counter that the energy savings are too modest to justify the maintenance costs associated with large-scale urban forestry programs, but recent empirical studies have begun to quantify the relationship between canopy density and measurable energy reductions.', $lyceon_json$[{"key":"A","text":"\"Neighborhoods with canopy coverage above 37 percent used 14.3 percent less air-conditioning electricity annually than those below 11 percent, after controlling for building age and household size.\""},{"key":"B","text":"\"Residents in tree-lined neighborhoods reported higher satisfaction with their community's appearance and expressed a willingness to pay an average of \\$23 more per month in property assessments to fund continued urban forestry maintenance programs.\""},{"key":"C","text":"\"Cities that invested in canopy expansion between 2009 and 2021 experienced a 19 percent decline in heat-related emergency room visits during peak summer months, a trend not observed in comparable cities that lacked such programs.\""},{"key":"D","text":"\"The average cost of planting and maintaining a street tree over a twenty-year period was estimated at \\$1,740, a figure that municipal budget analysts noted was substantially lower than initial projections had suggested for comparable infrastructure improvements.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The claim is that urban tree canopy coverage reduces residential energy consumption. The quotation reporting a 14.3 percent reduction in air-conditioning electricity use in high-canopy neighborhoods, with controls for confounding variables, directly quantifies the relationship between canopy density and energy savings. The quotation about resident satisfaction and willingness to pay for maintenance addresses community attitudes, not energy consumption. The quotation about heat-related emergency room visits supports a public health benefit of canopy expansion but does not address household energy use. The quotation about planting and maintenance costs addresses the economics of urban forestry programs but provides no evidence about energy consumption effects.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VD4LJ5', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the abnormally high salinity of the water nor the scarcity of dissolved oxygen ______ sufficient to explain the sudden decline of the endemic cichlid population in Lake Natron during the drought of 2017.', $lyceon_json$[{"key":"A","text":"were"},{"key":"B","text":"are"},{"key":"C","text":"have been"},{"key":"D","text":"was"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct choice is "was" because the sentence uses a "neither...nor" construction, which requires the verb to agree in number with the nearer subject. The nearer subject is "the scarcity of dissolved oxygen," which is singular, so the verb must be singular as well. Additionally, the phrase "during the drought of 2017" establishes a past time frame, requiring the past tense. The choice "were" uses the correct past tense but the incorrect plural number. The choice "are" is both plural and present tense, conflicting with both the singular nearer subject and the past time reference. The choice "have been" is also plural and uses the present perfect tense, which is inconsistent with the specific past event described.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VOX0W0', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of handwoven baskets displayed at the Tbilisi Ethnographic Museum ______ traditional weaving techniques that have been practiced in the Caucasus region for over three hundred years.', $lyceon_json$[{"key":"A","text":"illustrates"},{"key":"B","text":"illustrate"},{"key":"C","text":"illustrating"},{"key":"D","text":"have illustrated"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is "illustrates" because the subject of the sentence is "The collection," which is singular. The intervening prepositional phrase "of handwoven baskets displayed at the Tbilisi Ethnographic Museum" does not change the number of the subject. A singular subject requires a singular verb form. The choice "illustrate" is a plural verb form that incorrectly treats "baskets" as the subject. The choice "illustrating" is a participle that would leave the sentence without a main verb, creating a fragment. The choice "have illustrated" uses a plural auxiliary verb ("have") that does not agree with the singular subject "collection."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VYEU4I', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By analyzing the spectral signatures of light emitted by distant quasars and ______ the resulting data against models of early galactic formation, the astrophysics team at the Cerro Tololo observatory established that certain heavy elements appeared in the universe far earlier than standard nucleosynthesis theory had predicted.', $lyceon_json$[{"key":"A","text":"compared"},{"key":"B","text":"comparing"},{"key":"C","text":"having compared"},{"key":"D","text":"they compared"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "comparing" because the sentence uses the construction "By analyzing...and ______," which requires a parallel gerund form to match "analyzing." The coordinating conjunction "and" joins two gerund phrases that together form the prepositional phrase beginning with "By." The choice "compared" breaks parallel structure by introducing a past-tense verb where a gerund is required. The choice "having compared" uses a perfect participle that is not parallel with the present gerund "analyzing" and implies the comparison was completed before the analysis, which contradicts the logical sequence. The choice "they compared" introduces a new subject and finite verb, breaking the "By [gerund] and [gerund]" structure and creating a grammatically incoherent sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YTKCU8', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the recommendation in Text 1?', E'Text 1: Urban planner Miriam Okafor recommends that cities experiencing rapid population growth prioritize the construction of high-rise residential towers in their downtown cores. Concentrating housing vertically, she argues, reduces urban sprawl, shortens commute distances, and preserves surrounding agricultural land from development.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YY0ZE6', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'When the textile cooperative in rural Guatemala first began exporting its handwoven fabrics to European markets, many buyers assumed the intricate geometric patterns were purely decorative. In fact, each pattern ______ a specific aspect of the weaver''s community identity, encoding information about lineage, village affiliation, and ceremonial status within the design.', $lyceon_json$[{"key":"A","text":"signified"},{"key":"B","text":"concealed"},{"key":"C","text":"disparaged"},{"key":"D","text":"distributed across a wide area"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that each pattern encodes information about lineage, village affiliation, and ceremonial status, indicating the patterns represent or communicate meaning. "Signified" means to represent or indicate, which fits this communicative function. "Concealed" means to hide, which contradicts the passage''s point that the patterns encode visible information. "Disparaged" means to belittle or criticize, which is incoherent when applied to a pattern communicating identity. "Distributed across a wide area" introduces a spatial concept unrelated to the encoding of meaning within a design.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
